// === Récupération de l'item courant (réponse Claude) ===
const item = $input.item.json;

// === 1. Extraction du texte de la réponse ===
const rawText = item.content?.[0]?.text || '';

if (!rawText) {
  return {
    json: {
      synthese_error: true,
      error_reason: 'empty_response',
      claude_message_id: item.id || null
    }
  };
}

// === 2. Nettoyage markdown éventuel (PIÈGE-012 mitigation) ===
let cleanedText = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```\s*$/i, '')
  .trim();

// === 3. Parsing JSON ===
let synth;
try {
  synth = JSON.parse(cleanedText);
} catch (err) {
  return {
    json: {
      synthese_error: true,
      error_reason: 'json_parse_failed',
      error_detail: err.message,
      claude_message_id: item.id || null,
      raw_text: cleanedText.substring(0, 500)
    }
  };
}

// === 4. Récupération de l'article original ===
const articleData = $('1. Get articles à synthétiser').item.json;

// === 5. Cas synthèse impossible — retour propre ===
if (synth.synthese_impossible === true) {
  return {
    json: {
      article_id: articleData.id,
      synthese_impossible: true,
      raison_impossible: synth.raison || 'Non spécifié',
      tldr: null,
      contenu_synthese: null,
      citations: [],
      confiance: 0,
      citations_verifiees: 0,
      citations_a_verifier: 0,
      modele_utilise: item.model || 'claude-sonnet-4-6',
      tokens_input: item.usage?.input_tokens || 0,
      tokens_output: item.usage?.output_tokens || 0,
      cout_euros: ((item.usage?.input_tokens || 0) / 1000000 * 3 + (item.usage?.output_tokens || 0) / 1000000 * 15) * 0.93,
      claude_message_id: item.id || null,
      synthese_error: false
    }
  };
}

// === 6. Validation de structure pour cas standard ===
const errors = [];
if (typeof synth.tldr !== 'string') errors.push('tldr manquant');
if (typeof synth.synthese !== 'string') errors.push('synthese manquante');
if (!Array.isArray(synth.citations)) errors.push('citations non-tableau');
if (typeof synth.confiance !== 'number') errors.push('confiance invalide');

if (errors.length > 0) {
  return {
    json: {
      synthese_error: true,
      error_reason: 'validation_failed',
      error_detail: errors.join(' | '),
      raw_synthese: synth,
      claude_message_id: item.id || null,
      article_id: articleData.id
    }
  };
}

// === 7. Normalisation Unicode pour vérification des citations ===
function normalizeText(text) {
  if (!text) return '';
  return text
    // Décode entités HTML basiques
    .replace(/&amp;nbsp;/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    // Apostrophes typographiques → droites
    .replace(/[\u2018\u2019]/g, "'")
    // Guillemets typographiques → droits
    .replace(/[\u201C\u201D]/g, '"')
    // Espaces non-breaking, fines, etc. → espace simple
    .replace(/[\u00A0\u202F\u2009]/g, ' ')
    // Multi-espaces → un seul
    .replace(/\s+/g, ' ')
    .toLowerCase()
    .trim();
}

// === 8. Vérification de chaque citation contre TOUTES les métadonnées source ===
// Ce périmètre étendu (contenu + titre + url) reflète ce qui a été passé
// à l'IA dans le prompt user. Évite les faux positifs sur les références
// (numéros d'avis CERT-FR, IDs présents dans l'URL, etc.).
const sourceComplete = [
  articleData.contenu || '',
  articleData.titre || '',
  articleData.url || ''
].join(' | ');

const sourceNorm = normalizeText(sourceComplete);
let citationsVerifiees = 0;
let citationsAVerifier = 0;

const citationsAvecVerif = synth.citations.map(c => {
  const citNorm = normalizeText(c.texte);
  const present = sourceNorm.includes(citNorm);
  if (present) {
    citationsVerifiees++;
  } else {
    citationsAVerifier++;
  }
  return {
    texte: c.texte,
    contexte: c.contexte || '',
    verifiee: present
  };
});

// === 9. Calcul du coût ===
const inputTokens = item.usage?.input_tokens || 0;
const outputTokens = item.usage?.output_tokens || 0;
// Sonnet 4.6 : 3 $/Mtokens input, 15 $/Mtokens output
const coutUsd = (inputTokens / 1000000 * 3) + (outputTokens / 1000000 * 15);
const coutEuros = coutUsd * 0.93;

// === 10. Construction de l'objet final ===
return {
  json: {
    article_id: articleData.id,
    synthese_impossible: false,
    raison_impossible: null,
    tldr: synth.tldr,
    contenu_synthese: synth.synthese,
    citations: citationsAvecVerif,
    confiance: synth.confiance,
    citations_verifiees: citationsVerifiees,
    citations_a_verifier: citationsAVerifier,
    modele_utilise: item.model || 'claude-sonnet-4-6',
    tokens_input: inputTokens,
    tokens_output: outputTokens,
    cout_euros: coutEuros,
    claude_message_id: item.id || null,
    synthese_error: false
  }
};
